/**
 * FitQuest Expanded Exercise Generator
 * Generates 700+ exercises across all categories
 * This module creates variations programmatically to reach the target exercise count
 */

import type {
  Category,
  Difficulty,
  EquipmentLevel,
  EquipmentItem,
  TargetMuscle,
  TrainingType,
  ImpactLevel,
  SpaceFilter,
} from './types';

interface ExerciseTemplate {
  baseName: string;
  category: Category;
  baseDifficulty: Difficulty;
  equipment_level: EquipmentLevel;
  impact_level: ImpactLevel;
  space_required: SpaceFilter;
  time_per_set_seconds: number;
  baseInstructions: string[];
  primary_muscles: TargetMuscle[];
  secondary_muscles: TargetMuscle[];
  equipment_required: EquipmentItem[];
  equipment_optional: EquipmentItem[];
  training_types: { type: TrainingType; effectiveness: number }[];
  canAddTempo?: boolean;
  canAddPause?: boolean;
  canAddIsometric?: boolean;
  canAddPlyometric?: boolean;
  canAddUnilateral?: boolean;
  canAddElevated?: boolean;
  canAddWeighted?: boolean;
}

export interface GeneratedExercise {
  id: string;
  name: string;
  category: Category;
  difficulty: Difficulty;
  equipment_level: EquipmentLevel;
  impact_level: ImpactLevel;
  space_required: SpaceFilter;
  time_per_set_seconds: number;
  instructions: string[];
  order_in_category: number;
  primary_muscles: TargetMuscle[];
  secondary_muscles: TargetMuscle[];
  equipment_required: EquipmentItem[];
  equipment_optional: EquipmentItem[];
  training_types: { type: TrainingType; effectiveness: number }[];
  audio_intro?: string;
  audio_setup?: string;
  audio_execution?: string;
  audio_transition?: string;
}

