// ============================================
// VARIATION GENERATORS
// ============================================

// Global counter to ensure unique IDs across all templates
let globalVariationCounter = 0;

function generateVariations(template: ExerciseTemplate): GeneratedExercise[] {
  const exercises: GeneratedExercise[] = [];
  const categoryPrefixes: Record<Category, string> = {
    body_control: 'cal',
    posture: 'tall',
    speed: 'speed',
    mobility: 'flex',
    focus: 'mind',
    strength: 'muscle',
  };

  const prefix = categoryPrefixes[template.category];

  // Base exercise only — variations (Tempo/Pause/Isometric/Plyometric/Unilateral/Elevated/Weighted)
  // were removed to reduce DB bloat. Each base exercise is the canonical version with proper instructions.
  const baseId = `${prefix}_gen_${template.baseName.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${globalVariationCounter++}`;
  exercises.push({
    id: baseId,
    name: template.baseName,
    category: template.category,
    difficulty: template.baseDifficulty,
    equipment_level: template.equipment_level,
    impact_level: template.impact_level,
    space_required: template.space_required,
    time_per_set_seconds: template.time_per_set_seconds,
    instructions: template.baseInstructions,
    order_in_category: 0,
    primary_muscles: template.primary_muscles,
    secondary_muscles: template.secondary_muscles,
    equipment_required: template.equipment_required,
    equipment_optional: template.equipment_optional,
    training_types: template.training_types,
  });

  return exercises;
}

// ============================================
// MAIN EXPORT
// ============================================

export function generateAllExercises(): GeneratedExercise[] {
  // Reset global counter for each generation pass
  globalVariationCounter = 0;

  const allTemplates = [
    ...PUSH_TEMPLATES,
    ...PULL_TEMPLATES,
    ...LEG_TEMPLATES,
    ...CORE_TEMPLATES,
    ...FLEXIBILITY_TEMPLATES,
    ...POSTURE_TEMPLATES,
    ...SPEED_TEMPLATES,
    ...MENTAL_CLARITY_TEMPLATES,
    ...MUSCLE_BUILDING_TEMPLATES,
    // New expanded templates for 722 exercises
    ...MOBILITY_TEMPLATES,
    ...CARDIO_TEMPLATES,
    ...BALANCE_TEMPLATES,
    ...RECOVERY_TEMPLATES,
    ...FUNCTIONAL_TEMPLATES,
    ...SPORT_SPECIFIC_TEMPLATES,
    // Extra templates to reach 722 target
    ...EXTRA_MOBILITY_TEMPLATES,
    ...EXTRA_CARDIO_TEMPLATES,
    ...EXTRA_BALANCE_TEMPLATES,
    ...EXTRA_RECOVERY_TEMPLATES,
    ...EXTRA_FUNCTIONAL_TEMPLATES,
    ...EXTRA_SPORT_TEMPLATES,
    // Bonus high-variation templates
    ...BONUS_TEMPLATES,
    // Yoga poses (from yoga-poses-dataset)
    ...YOGA_TEMPLATES,
  ];

  const exercises: GeneratedExercise[] = [];

  for (const template of allTemplates) {
    exercises.push(...generateVariations(template));
  }

  // Assign order within category
  const categoryCounters: Record<string, number> = {};
  for (const exercise of exercises) {
    if (!categoryCounters[exercise.category]) {
      categoryCounters[exercise.category] = 1;
    }
    exercise.order_in_category = categoryCounters[exercise.category]!++;
  }

  if (__DEV__)
    console.warn(`[ExerciseGenerator] Generated ${exercises.length} exercises from ${allTemplates.length} templates`);
  return exercises;
}

export type { GeneratedExercise as GeneratedExerciseType };
